import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"模型与排序","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/models.md","filePath":"zh/guide/models.md","lastUpdated":1793111003000}'),o={name:"zh/guide/models.md"};function s(n,t,h,p,i,l){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="模型与排序" tabindex="-1">模型与排序 <a class="header-anchor" href="#模型与排序" aria-label="Permalink to &quot;模型与排序&quot;">​</a></h1><p>语言模型负责检索规划与相关性评估，可选初排序帮助选择进入最终模型评分的候选。</p><h2 id="连接模型" tabindex="-1">连接模型 <a class="header-anchor" href="#连接模型" aria-label="Permalink to &quot;连接模型&quot;">​</a></h2><p>社区版或在线版自带密钥模式中，打开<strong>设置 → 模型 API → 添加连接</strong>，选择连接类型、服务商与模型，再确认 Key、基础地址和协议。预设只是起点，模型必须在服务商处实际可用。</p><p>模型弹窗中的<strong>测试连接</strong>只检查当前草稿，不会保存。点击<strong>保存</strong>后，才能创建或更新连接，并将它选为检索或写作模型。数据源弹窗中的测试会先保存，行为不同，详见<a href="./sources">数据源</a>。</p><table tabindex="0"><thead><tr><th>协议</th><th>接口操作</th></tr></thead><tbody><tr><td>OpenAI Chat Completions</td><td><code>/chat/completions</code></td></tr><tr><td>OpenAI Responses</td><td><code>/responses</code></td></tr><tr><td>Anthropic Messages</td><td><code>/v1/messages</code></td></tr></tbody></table><p>基础地址应符合协议要求，不要重复拼接请求路径。兼容 Chat Completions 不等于兼容 Responses。</p><p>PaperSeek 服务只提供模型下拉菜单，地址和密钥由 PaperSeek 管理。</p><h2 id="初排序方式" tabindex="-1">初排序方式 <a class="header-anchor" href="#初排序方式" aria-label="Permalink to &quot;初排序方式&quot;">​</a></h2><p><strong>默认使用本地融合。</strong></p><table tabindex="0"><thead><tr><th>方式</th><th>行为</th><th>额外服务</th></tr></thead><tbody><tr><td>本地融合</td><td>综合本地词法、哈希语义信号与多路召回排名</td><td>无需</td></tr><tr><td>Embedding + Rerank</td><td>最终候选选择前的外部向量与重排序</td><td>Embedding 和 Rerank API</td></tr><tr><td>决策模型</td><td>使用 System One 协议评估本地融合后的候选</td><td>兼容决策 API</td></tr></tbody></table><p>本地融合只指初排序，整次检索仍需要语言模型和网络请求。</p><p>决策路径最多评估最终 LLM 候选预算两倍的文献，再选最终子集，仍受实际候选数和预算约束。</p><h2 id="不同版本的设置" tabindex="-1">不同版本的设置 <a class="header-anchor" href="#不同版本的设置" aria-label="Permalink to &quot;不同版本的设置&quot;">​</a></h2><p><strong>社区版 / 自带密钥</strong>：可配置模型路由和凭据，写作模型可以与检索模型不同。</p><p><strong>PaperSeek 服务</strong>：检索使用 Auto，综述写作可选 Fast 或 Deep Research，保留初排序方式选择，地址和密钥留在服务端。</p><h2 id="本地模型" tabindex="-1">本地模型 <a class="header-anchor" href="#本地模型" aria-label="Permalink to &quot;本地模型&quot;">​</a></h2><p>社区版支持运行设备可连接到的兼容模型服务，包括回环地址。</p><p>在线版自带密钥模式会拒绝回环、内网、链路本地等不安全目的地，以防止 SSRF。<code>127.0.0.1</code> 指向在线服务器，不是你的笔记本；本地端点请使用社区版。</p><h2 id="降级与失败" tabindex="-1">降级与失败 <a class="header-anchor" href="#降级与失败" aria-label="Permalink to &quot;降级与失败&quot;">​</a></h2><p>可选排序失败时，程序可能保留本地顺序并显示警告，不代表外部排序成功。应查看本次记录的配置和执行状态。</p><p>鉴权、余额、速率限制、超时和响应格式错误需要不同处理方式，见<a href="./../reference/troubleshooting">常见问题</a>。</p>',22)])])}const b=e(o,[["render",s]]);export{m as __pageData,b as default};
